# calculate the font size based on the number of characters in the tag path;
# font size cannot be smaller than 8px

tagPathLength = len(value)
fontSize = 17 - (0.027027*tagPathLength)
if fontSize < 8:
	return '8px'
else:
	return str(fontSize) + 'px'

# display the path of the selected tag so that the user knows which tag they
# are editing the alarms for when they are viewing the property editor

if len(value.keys()) > 0:
	return 'Tag: ' + str(value['path'])
else:
	return 'Tag:'

# when the tagConfig or selectedRow param changes, this determines either which
# alarm object should be passed to the property editor, or if an empty object
# should be passed (because no alarm is selected)

selectedRow = value['selectedRow']
config = value['tagConfig']

if selectedRow == None:
	return {}
else:
	# selectedRow not equal to None, find the alarm in the tagConfig alarm list
	# and return the object
	if 'alarms' in config.keys():
		logger = system.util.getLogger('configurator.sm.properties')
		logger.debug('alarm param populated; alarm= ' + str(config['alarms'][selectedRow]))

		return config['alarms'][selectedRow]
	else:
		return {}

# in order to prevent duplicate alarm names, pass in the names for all the
# alarms that this tag has; then, when user changes alarm name, can check
# to see if it is a duplicate or not

if len(value.keys()) > 0:
	alarmNames = []
	if 'alarms' in value.keys():
		for alarm in value['alarms']:
			alarmNames.append(alarm['name'])
	return alarmNames
else:
	return []

# check to see if this alarm is a UDT alarm, and if it is, get the object
# that represents the alarm in the UDT definition and pass it to the
# property editor; if this alarm is not a UDT alarm, then return an empty object

logger = system.util.getLogger('configurator.sm.properties')

if 'name' in value.keys():
	currAlarmName = value['name']
else:
	currAlarmName = 'Alarm'

for alarm in self.view.params.udtDefAlarms:
	if currAlarmName == alarm['name']:
		logger.debug('alarm is a UDT alarm; alarm name= ' + str(currAlarmName))
		return alarm

logger.debug('alarm is not a UDT alarm; alarm name= ' + str(currAlarmName))
return {}

# return the name of the alarm; if 'name' is not in alarm object's keys,
# then name is set to default 'Alarm'

if 'name' in value.keys():
	return value['name']
else:
	return ''

# only display 'commit' and 'revert' buttons if a tag is selected,
# the binding editor is not open and the tag tree is not open.

if len(value['tag']) == 0:
	return False
else:
	if value['bindingEditorOpen'] == True or value['tagTreeOpen']:
		return False
	else:
		return True
